PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,name TEXT NOT NULL,email TEXT NOT NULL UNIQUE COLLATE NOCASE,password_hash TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN('STUDENT','FACULTY','ADMIN')),department TEXT NOT NULL,identifier TEXT,status TEXT NOT NULL DEFAULT 'ACTIVE' CHECK(status IN('ACTIVE','SUSPENDED')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,csrf TEXT NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS resources(id INTEGER PRIMARY KEY,owner_id INTEGER NOT NULL REFERENCES users(id),title TEXT NOT NULL,description TEXT NOT NULL,category TEXT NOT NULL,subtype TEXT NOT NULL DEFAULT 'OTHER',condition TEXT NOT NULL CHECK(condition IN('NEW','GOOD','FAIR','WORN')),mode TEXT NOT NULL CHECK(mode IN('BORROW','EXCHANGE','BOTH')),pickup TEXT NOT NULL,max_days INTEGER NOT NULL DEFAULT 14 CHECK(max_days BETWEEN 1 AND 365),status TEXT NOT NULL DEFAULT 'AVAILABLE' CHECK(status IN('AVAILABLE','RESERVED','ARCHIVED')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_resources_search ON resources(status,category,mode);
CREATE TABLE IF NOT EXISTS requests(id INTEGER PRIMARY KEY,requester_id INTEGER NOT NULL REFERENCES users(id),title TEXT NOT NULL,description TEXT NOT NULL,category TEXT NOT NULL,intent TEXT NOT NULL CHECK(intent IN('BORROW','EXCHANGE')),pickup TEXT NOT NULL,duration_days INTEGER NOT NULL DEFAULT 7 CHECK(duration_days BETWEEN 1 AND 365),status TEXT NOT NULL DEFAULT 'OPEN' CHECK(status IN('OPEN','MATCHED','CANCELLED','COMPLETED')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS offers(id INTEGER PRIMARY KEY,request_id INTEGER NOT NULL REFERENCES requests(id),resource_id INTEGER NOT NULL REFERENCES resources(id),owner_id INTEGER NOT NULL REFERENCES users(id),state TEXT NOT NULL DEFAULT 'PENDING' CHECK(state IN('PENDING','ACCEPTED','DECLINED','CANCELLED')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(request_id,resource_id));
CREATE INDEX IF NOT EXISTS idx_offers_owner ON offers(owner_id,state);
CREATE TABLE IF NOT EXISTS transactions(id INTEGER PRIMARY KEY,request_id INTEGER NOT NULL UNIQUE REFERENCES requests(id),offer_id INTEGER NOT NULL UNIQUE REFERENCES offers(id),resource_id INTEGER NOT NULL REFERENCES resources(id),owner_id INTEGER NOT NULL REFERENCES users(id),borrower_id INTEGER NOT NULL REFERENCES users(id),status TEXT NOT NULL DEFAULT 'PENDING_HANDOVER' CHECK(status IN('PENDING_HANDOVER','ACTIVE','RETURN_PENDING_CONFIRMATION','COMPLETED','CANCELLED','DISPUTED')),due_at TEXT,handover_by_owner INTEGER NOT NULL DEFAULT 0,handover_by_borrower INTEGER NOT NULL DEFAULT 0,return_by_borrower INTEGER NOT NULL DEFAULT 0,return_by_owner INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,completed_at TEXT);
CREATE TABLE IF NOT EXISTS messages(id INTEGER PRIMARY KEY,transaction_id INTEGER NOT NULL REFERENCES transactions(id),sender_id INTEGER NOT NULL REFERENCES users(id),body TEXT NOT NULL CHECK(length(body) BETWEEN 1 AND 2000),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_messages_transaction ON messages(transaction_id,id);
CREATE TABLE IF NOT EXISTS notifications(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,kind TEXT NOT NULL,text TEXT NOT NULL,link TEXT,read_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_notifications_user ON notifications(user_id,read_at,id);
CREATE TABLE IF NOT EXISTS ratings(id INTEGER PRIMARY KEY,transaction_id INTEGER NOT NULL REFERENCES transactions(id),from_user INTEGER NOT NULL REFERENCES users(id),to_user INTEGER NOT NULL REFERENCES users(id),stars INTEGER NOT NULL CHECK(stars BETWEEN 1 AND 5),review TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(transaction_id,from_user),CHECK(from_user<>to_user));
CREATE TABLE IF NOT EXISTS reports(id INTEGER PRIMARY KEY,reporter_id INTEGER NOT NULL REFERENCES users(id),target_type TEXT NOT NULL,target_id INTEGER NOT NULL,reason TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'OPEN' CHECK(status IN('OPEN','RESOLVED','DISMISSED')),resolution TEXT,resolved_by INTEGER REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,resolved_at TEXT);
CREATE TABLE IF NOT EXISTS audit_events(id INTEGER PRIMARY KEY,actor_id INTEGER REFERENCES users(id),action TEXT NOT NULL,target_type TEXT NOT NULL,target_id INTEGER NOT NULL,details TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
